TWComponent.script:
function addSQLParameter(value) {
	if (value === null || value === undefined) {
		value = "";
	} else if (typeof value === "string") {
		value = value || "";
	} else if (typeof value === "number") {
		value = value || 0;
	} else if (typeof value === "boolean") {
		value = value ? "1" : "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}

tw.local.sqlStats = new tw.object.listOf.SQLStatement();
var index = 0;

//lock
tw.local.sqlStats[index] = new tw.object.SQLStatement();
tw.local.sqlStats[index].sql = "SELECT * FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE ID = ? FOR UPDATE";
tw.local.sqlStats[index].parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID));
index++;

//update
tw.local.sqlStats[index] = new tw.object.SQLStatement();
tw.local.sqlStats[index].parameters = new tw.object.listOf.SQLParameter();

//user deleted the transaction
if (tw.local.transaction.remove) {
	//fixed parameters
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.referenceNumber));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.postingDate));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.amountAllocatedForCurrencyRequest));

	//whole amount was added only in this request. It was not added by another request
	if (tw.local.amountResult[0].rows.listLength == 0 || (tw.local.amountResult[0].rows.listLength == 1 && tw.local.amountResult[0].rows[0].data[0] == tw.local.transaction.requestID)) {
		tw.local.sqlStats[index].sql = "UPDATE " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION " + "SET AMOUNTLINKEDINBPM = (SELECT AMOUNTLINKEDINBPM FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE)) - ? " + ",  AMOUNTFORCURRENTREQ = ? , AMOUNTINREQCURRENCY = ? WHERE ID = ?";
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.amountAllocatedForCurrencyRequest));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.allocatedAmountInRequestCurrency));
	}
	//part of the amount was added in another request(s)
	else {
		tw.local.sqlStats[index].sql =
			"UPDATE " +
			tw.env.LKP_DB_Schema +
			".ODC_FCTRANSACTION " +
			"SET AMOUNTLINKEDINBPM = (SELECT AMOUNTLINKEDINBPM FROM " +
			tw.env.LKP_DB_Schema +
			".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE)) - ? " +
			",  AMOUNTFORCURRENTREQ = (SELECT AMOUNTINCURRENTREQ FROM " +
			tw.env.LKP_DB_Schema +
			".ODC_SELECTEDTRANSACTIONS WHERE ID = (SELECT MAX(ID) FROM " +
			tw.env.LKP_DB_Schema +
			".ODC_SELECTEDTRANSACTIONS WHERE REQUESTID <> ? AND isDeleted <> 'Yes' AND TRANSACTIONID = ? GROUP BY TRANSACTIONID )) " +
			",  AMOUNTINREQCURRENCY = (SELECT AMOUNTINREQCURRENCY FROM " +
			tw.env.LKP_DB_Schema +
			".ODC_SELECTEDTRANSACTIONS WHERE ID = (SELECT MAX(ID) FROM " +
			tw.env.LKP_DB_Schema +
			".ODC_SELECTEDTRANSACTIONS WHERE REQUESTID <> ? AND isDeleted <> 'Yes' AND TRANSACTIONID = ? GROUP BY TRANSACTIONID ))" +
			"WHERE ID = ?";
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.requestID));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.requestID));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID));
	}
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID));
	index++;

	//updated odc_selectedtransactions table
	tw.local.sqlStats[index] = new tw.object.SQLStatement();
	tw.local.sqlStats[index].sql = "UPDATE " + tw.env.LKP_DB_Schema + ".ODC_SELECTEDTRANSACTIONS SET ISDELETED = 'Yes' " + "WHERE REQUESTID = ? AND TRANSACTIONID = ?;";
	tw.local.sqlStats[index].parameters = new tw.object.listOf.SQLParameter();
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.requestID));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID));

	log.info("Transaction removed: " + tw.local.transactionID);
}

//user updated the transaction
else {
	////amount was added only in this request. It was not added by another request
	if (tw.local.amountResult[0].rows.listLength == 0 || (tw.local.amountResult[0].rows.listLength == 1 && tw.local.amountResult[0].rows[0].data[0] == tw.local.transaction.requestID)) {
		tw.local.sqlStats[index].sql = "UPDATE " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION " + "SET AMOUNTLINKEDINBPM = ? ,  AMOUNTFORCURRENTREQ = ?,  AMOUNTINREQCURRENCY = ? WHERE ID = ?";
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.amountAllocatedForCurrencyRequest));
	}
	//part of the amount was added by another request(s)
	else {
		tw.local.sqlStats[index].sql =
			"UPDATE " +
			tw.env.LKP_DB_Schema +
			".ODC_FCTRANSACTION " +
			"SET AMOUNTLINKEDINBPM = ( " +
			"SELECT CASE " +
			"WHEN ? = 0 THEN AMOUNTLINKEDINBPM + ? " + // if previousAmount = 0 -->add allocated
			"ELSE AMOUNTLINKEDINBPM - ? + ? " + // else subtract previous, then add allocated
			"END " +
			"FROM " +
			tw.env.LKP_DB_Schema +
			".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE) " +
			"), AMOUNTFORCURRENTREQ = ?, AMOUNTINREQCURRENCY = ? WHERE ID = ?";

		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.previousAmount));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.amountAllocatedForCurrencyRequest));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.previousAmount));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.amountAllocatedForCurrencyRequest));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.referenceNumber));
		tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.postingDate));

		log.info("Previous amount: " + tw.local.transaction.previousAmount);
		log.info("Allocated amount: " + tw.local.transaction.amountAllocatedForCurrencyRequest);
	}

	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.amountAllocatedForCurrencyRequest));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.allocatedAmountInRequestCurrency));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID));
	index++;

	//insert into odc_selectedtransactions table
	tw.local.sqlStats[index] = new tw.object.SQLStatement();
	tw.local.sqlStats[index].sql = "INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_SELECTEDTRANSACTIONS ( " + "REQUESTID, TRANSACTIONID, AMOUNTLINKEDINBPM, AMOUNTINCURRENTREQ, AMOUNTINREQCURRENCY,ISDELETED) " + "VALUES (?, ?, (SELECT AMOUNTLINKEDINBPM FROM " + tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION WHERE REFERENCENO = ? AND CAST(POSTINGDATE AS DATE) = CAST(? AS DATE)) " + ",?,?,?)";
	tw.local.sqlStats[index].parameters = new tw.object.listOf.SQLParameter();
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.requestID));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transactionID));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.referenceNumber));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.postingDate));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.amountAllocatedForCurrencyRequest));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter(tw.local.transaction.allocatedAmountInRequestCurrency));
	tw.local.sqlStats[index].parameters.insertIntoList(tw.local.sqlStats[index].parameters.listLength, addSQLParameter("No"));
}

